1	package server
2	
3	import (
4		"net/http"
5		"sort"
6	)
7	
8	type createSnapshotInput struct {
9		ID                 string `json:"id"`
10		ExpectedGeneration *int64 `json:"expectedGeneration"`
11	}
12	
13	type createCloneInput struct {
14		ID     string `json:"id"`
15		PoolID string `json:"poolId"`
16	}
17	
18	// snapshotView is the public representation of an in-memory volume snapshot.
19	type snapshotView struct {
20		ID               string `json:"id"`
21		SourceVolumeID   string `json:"sourceVolumeId"`
22		PoolID           string `json:"poolId"`
23		SizeBytes        int64  `json:"sizeBytes"`
24		SourceGeneration int64  `json:"sourceGeneration"`
25	}
26	
27	// snapshot is an immutable, in-memory copy of a volume's size at a given
28	// generation. It deliberately does not reference the live source volume: once
29	// taken it is independent, so later changes to or deletion of the source do
30	// not affect it. Its size charges the source pool until the snapshot is
31	// deleted. tenant is inherited from the source volume. sourceInstanceID pins
32	// the snapshot to the exact volume instance that produced it, so a snapshot
33	// can only be restored into that instance — never into a later volume that
34	// happens to reuse the same id.
35	type snapshot struct {
36		id               string
37		sourceVolumeID   string
38		poolID           string
39		sizeBytes        int64
40		sourceGeneration int64
41		tenant           string
42		sourceInstanceID int64
43	}
44	
45	func (s *snapshot) view() snapshotView {
46		return snapshotView{
47			ID:               s.id,
48			SourceVolumeID:   s.sourceVolumeID,
49			PoolID:           s.poolID,
50			SizeBytes:        s.sizeBytes,
51			SourceGeneration: s.sourceGeneration,
52		}
53	}
54	
55	// routeSnapshots dispatches /v1/snapshots and its sub-paths.
56	func (s *store) routeSnapshots(w http.ResponseWriter, r *http.Request) {
57		parts := splitPath(r.URL.Path, snapshotPath)
58		for _, seg := range parts {
59			if seg == "" {
60				writeError(w, http.StatusNotFound, "not_found")
61				return
62			}
63		}
64		switch {
65		case len(parts) == 0:
66			if r.Method != http.MethodGet {
67				methodNotAllowed(w, http.MethodGet)
68				return
69			}
70			s.listSnapshots(w)
71		case len(parts) == 1:
72			switch r.Method {
73			case http.MethodGet:
74				s.getSnapshot(w, parts[0])
75			case http.MethodDelete:
76				s.deleteSnapshot(w, parts[0])
77			default:
78				methodNotAllowed(w, http.MethodGet, http.MethodDelete)
79			}
80		case len(parts) == 2 && parts[1] == "clones":
81			if r.Method != http.MethodPost {
82				methodNotAllowed(w, http.MethodPost)
83				return
84			}
85			s.createClone(w, r, parts[0])
86		default:
87			writeError(w, http.StatusNotFound, "not_found")
88		}
89	}
90	
91	func (s *store) listSnapshots(w http.ResponseWriter) {
92		s.mu.RLock()
93		defer s.mu.RUnlock()
94		ids := make([]string, 0, len(s.snapshots))
95		for id := range s.snapshots {
96			ids = append(ids, id)
97		}
98		sort.Strings(ids)
99		items := make([]snapshotView, 0, len(ids))
100		for _, id := range ids {
101			items = append(items, s.snapshots[id].view())
102		}
103		writeJSON(w, http.StatusOK, map[string]any{"items": items})
104	}
105	
106	func (s *store) getSnapshot(w http.ResponseWriter, id string) {
107		if !validID(id) {
108			writeError(w, http.StatusBadRequest, "invalid_request")
109			return
110		}
111		s.mu.RLock()
112		snap, ok := s.snapshots[id]
113		var view snapshotView
114		if ok {
115			view = snap.view()
116		}
117		s.mu.RUnlock()
118		if !ok {
119			writeError(w, http.StatusNotFound, "snapshot_not_found")
120			return
121		}
122		writeJSON(w, http.StatusOK, view)
123	}
124	
125	// createSnapshot handles POST /v1/volumes/{volumeId}/snapshots.
126	func (s *store) createSnapshot(w http.ResponseWriter, r *http.Request, volumeID string) {
127		var in createSnapshotInput
128		if !decodeRequest(r, &in) {
129			writeError(w, http.StatusBadRequest, "invalid_request")
130			return
131		}
132		if !validID(volumeID) || !validID(in.ID) || in.ExpectedGeneration == nil || *in.ExpectedGeneration < 0 {
133			writeError(w, http.StatusBadRequest, "invalid_request")
134			return
135		}
136		expected := *in.ExpectedGeneration
137	
138		s.mu.Lock()
139		defer s.mu.Unlock()
140		// A retry of the same id wins its idempotency/conflict check before the
141		// source is looked up, so deleting the source after a successful snapshot
142		// keeps the retry returning 200.
143		if existing, dup := s.snapshots[in.ID]; dup {
144			if existing.sourceVolumeID == volumeID && existing.sourceGeneration == expected {
145				writeJSON(w, http.StatusOK, existing.view())
146				return
147			}
148			writeError(w, http.StatusConflict, "snapshot_exists")
149			return
150		}
151		v, ok := s.volumes[volumeID]
152		if !ok {
153			writeError(w, http.StatusNotFound, "volume_not_found")
154			return
155		}
156		if v.binding != "" {
157			writeError(w, http.StatusConflict, "volume_in_use")
158			return
159		}
160		if v.generation != expected {
161			writeError(w, http.StatusConflict, "stale_generation")
162			return
163		}
164		p := s.pools[v.poolID]
165		// The store lock makes the quota and capacity checks plus the charge
166		// atomic, so concurrent snapshots can never exceed either limit. The
167		// snapshot inherits the source volume's tenant.
168		if p.tenantQuotaExceeded(v.tenant, v.sizeBytes) {
169			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
170			return
171		}
172		if p.allocated() > p.rawCapacity-v.sizeBytes {
173			writeError(w, http.StatusConflict, "insufficient_capacity")
174			return
175		}
176		snap := &snapshot{
177			id:               in.ID,
178			sourceVolumeID:   volumeID,
179			poolID:           v.poolID,
180			sizeBytes:        v.sizeBytes,
181			sourceGeneration: v.generation,
182			tenant:           v.tenant,
183			sourceInstanceID: v.instanceID,
184		}
185		s.snapshots[in.ID] = snap
186		p.snapshotBytes += v.sizeBytes
187		p.tenantUsed[v.tenant] += v.sizeBytes
188		s.appendAudit(auditSnapshotCreated, snapshotPath+"/"+in.ID, v.poolID, v.sizeBytes)
189		writeJSON(w, http.StatusCreated, snap.view())
190	}
191	
192	func (s *store) deleteSnapshot(w http.ResponseWriter, id string) {
193		if !validID(id) {
194			writeError(w, http.StatusBadRequest, "invalid_request")
195			return
196		}
197		s.mu.Lock()
198		defer s.mu.Unlock()
199		snap, ok := s.snapshots[id]
200		if !ok {
201			writeError(w, http.StatusNotFound, "snapshot_not_found")
202			return
203		}
204		s.pools[snap.poolID].snapshotBytes -= snap.sizeBytes
205		s.pools[snap.poolID].tenantUsed[snap.tenant] -= snap.sizeBytes
206		delete(s.snapshots, id)
207		s.appendAudit(auditSnapshotDeleted, snapshotPath+"/"+id, snap.poolID, -snap.sizeBytes)
208		w.WriteHeader(http.StatusNoContent)
209	}
210	
211	// createClone handles POST /v1/snapshots/{id}/clones.
212	func (s *store) createClone(w http.ResponseWriter, r *http.Request, snapshotID string) {
213		var in createCloneInput
214		if !decodeRequest(r, &in) {
215			writeError(w, http.StatusBadRequest, "invalid_request")
216			return
217		}
218		if !validID(snapshotID) || !validID(in.ID) || !validID(in.PoolID) {
219			writeError(w, http.StatusBadRequest, "invalid_request")
220			return
221		}
222	
223		s.mu.Lock()
224		defer s.mu.Unlock()
225		snap, ok := s.snapshots[snapshotID]
226		if !ok {
227			writeError(w, http.StatusNotFound, "snapshot_not_found")
228			return
229		}
230		// A clone is an ordinary volume, so its id shares the global volume
231		// namespace. Once the snapshot is confirmed, the volume-id conflict check
232		// decides: a retry from the same snapshot into the same pool is 200, while
233		// an id owned by any other creation or a different pool is 409.
234		if existing, dup := s.volumes[in.ID]; dup {
235			if existing.cloneSource == snapshotID && existing.poolID == in.PoolID {
236				writeJSON(w, http.StatusOK, existing.view())
237				return
238			}
239			writeError(w, http.StatusConflict, "volume_exists")
240			return
241		}
242		target, ok := s.pools[in.PoolID]
243		if !ok {
244			writeError(w, http.StatusNotFound, "pool_not_found")
245			return
246		}
247		// The clone inherits the snapshot's tenant and charges the target pool.
248		if target.tenantQuotaExceeded(snap.tenant, snap.sizeBytes) {
249			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
250			return
251		}
252		if target.allocated() > target.rawCapacity-snap.sizeBytes {
253			writeError(w, http.StatusConflict, "insufficient_capacity")
254			return
255		}
256		v := &volume{id: in.ID, poolID: in.PoolID, sizeBytes: snap.sizeBytes, createdSizeBytes: snap.sizeBytes, cloneSource: snapshotID, tenant: snap.tenant}
257		s.volumeInstanceSeq++
258		v.instanceID = s.volumeInstanceSeq
259		s.volumes[in.ID] = v
260		target.volumeBytes += snap.sizeBytes
261		target.tenantUsed[snap.tenant] += snap.sizeBytes
262		s.appendAudit(auditCloneCreated, volumePath+"/"+in.ID, in.PoolID, snap.sizeBytes)
263		writeJSON(w, http.StatusCreated, v.view())
264	}
