package server

import (
	"math"
	"net/http"
	"sort"
	"sync"
)

// deviceInput is one member of a create-pool request.
type deviceInput struct {
	ID            string `json:"id"`
	CapacityBytes int64  `json:"capacityBytes"`
	FaultDomain   string `json:"faultDomain"`
}

type createPoolInput struct {
	ID      string        `json:"id"`
	Devices []deviceInput `json:"devices"`
}

type reservationInput struct {
	RequestID string `json:"requestId"`
	Bytes     int64  `json:"bytes"`
}

// deviceView is the public representation of a pool device.
type deviceView struct {
	ID            string `json:"id"`
	CapacityBytes int64  `json:"capacityBytes"`
	FaultDomain   string `json:"faultDomain"`
}

// poolView is the public representation of a storage pool.
type poolView struct {
	ID               string       `json:"id"`
	Devices          []deviceView `json:"devices"`
	RawCapacityBytes int64        `json:"rawCapacityBytes"`
	AllocatedBytes   int64        `json:"allocatedBytes"`
	AvailableBytes   int64        `json:"availableBytes"`
}

// reservationView is the result of a successful reservation request.
type reservationView struct {
	PoolID    string `json:"poolId"`
	RequestID string `json:"requestId"`
	Bytes     int64  `json:"bytes"`
}

type reservation struct {
	requestID string
	bytes     int64
	tenant    string
}

// pool is one storage pool. tenantUsed tracks each tenant's charged bytes
// (reservations + volumes + snapshots + objects) inside the pool; quotas maps
// a tenant id to its byte limit. Tenants without a quota entry are unlimited.
type pool struct {
	id            string
	devices       []deviceInput
	rawCapacity   int64
	reservations  map[string]reservation
	volumeBytes   int64 // total sizeBytes of volumes in this pool
	snapshotBytes int64 // total sizeBytes of snapshots held in this pool
	objectBytes   int64 // total sizeBytes of objects in buckets of this pool
	tenantUsed    map[string]int64
	quotas        map[string]int64
}

// volume is a capacity allocation inside a pool with an optional exclusive
// node binding. generation is bumped on every binding state change, every
// resize and every restore. cloneSource records the snapshot a volume was
// cloned from ("" for a volume created directly) so clone retries can be told
// apart from foreign ids. createdSizeBytes records the size from the original
// creation request (the snapshot size for clones); idempotent create replays
// match it rather than the live sizeBytes, so resizing a volume never turns a
// faithful retry into a volume_exists conflict. tenant is the owning tenant;
// its current sizeBytes is charged to the tenant's usage in the pool.
// instanceID distinguishes successive volumes that reuse the same id: it is
// assigned from the store-wide sequence at creation, so a snapshot taken from
// a deleted volume never matches a later volume recreated under the same id.
type volume struct {
	id               string
	poolID           string
	sizeBytes        int64
	createdSizeBytes int64
	generation       int64
	binding          string // "" when unbound
	cloneSource      string // snapshot id when produced via a clone
	tenant           string
	instanceID       int64
}

func (p *pool) allocated() int64 {
	var total int64 = p.volumeBytes + p.snapshotBytes + p.objectBytes
	for _, r := range p.reservations {
		total += r.bytes
	}
	return total
}

func (p *pool) view() poolView {
	devices := make([]deviceView, len(p.devices))
	for i, d := range p.devices {
		devices[i] = deviceView{ID: d.ID, CapacityBytes: d.CapacityBytes, FaultDomain: d.FaultDomain}
	}
	allocated := p.allocated()
	return poolView{
		ID:               p.id,
		Devices:          devices,
		RawCapacityBytes: p.rawCapacity,
		AllocatedBytes:   allocated,
		AvailableBytes:   p.rawCapacity - allocated,
	}
}

// store is the in-memory state of the service. It is wiped on restart.
type store struct {
	mu          sync.RWMutex
	pools       map[string]*pool
	volumes     map[string]*volume
	snapshots   map[string]*snapshot
	buckets     map[string]*bucket
	deviceOwner map[string]string
	// auditEvents is the append-only audit log; auditSeq is the sequence of
	// its last entry (0 while empty). Both are mutated under mu, together with
	// the business state each event describes.
	auditEvents []auditEvent
	auditSeq    int64
	// volumeInstanceSeq is the sequence of the last assigned volume instance
	// id (0 while none). It is incremented under mu at every volume creation,
	// so a recreated volume never shares an instance id with its predecessor.
	volumeInstanceSeq int64
}

func newStore() *store {
	return &store{
		pools:       make(map[string]*pool),
		volumes:     make(map[string]*volume),
		snapshots:   make(map[string]*snapshot),
		buckets:     make(map[string]*bucket),
		deviceOwner: make(map[string]string),
	}
}

func validID(id string) bool {
	return idPattern.MatchString(id)
}

func (s *store) listPools(w http.ResponseWriter) {
	s.mu.RLock()
	ids := make([]string, 0, len(s.pools))
	for id := range s.pools {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	items := make([]poolView, 0, len(ids))
	for _, id := range ids {
		items = append(items, s.pools[id].view())
	}
	s.mu.RUnlock()
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

func (s *store) getPool(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.RLock()
	p, ok := s.pools[id]
	var v poolView
	if ok {
		v = p.view()
	}
	s.mu.RUnlock()
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	writeJSON(w, http.StatusOK, v)
}

func (s *store) createPool(w http.ResponseWriter, r *http.Request) {
	var in createPoolInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	// Validate the whole payload before touching any state so a failure
	// never leaves a partial pool behind.
	if !validID(in.ID) || len(in.Devices) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	seen := make(map[string]bool, len(in.Devices))
	var rawCapacity int64
	for _, d := range in.Devices {
		if !validID(d.ID) || d.CapacityBytes <= 0 || d.FaultDomain == "" || seen[d.ID] {
			writeError(w, http.StatusBadRequest, "invalid_request")
			return
		}
		if rawCapacity > math.MaxInt64-d.CapacityBytes {
			writeError(w, http.StatusBadRequest, "invalid_request")
			return
		}
		seen[d.ID] = true
		rawCapacity += d.CapacityBytes
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.pools[in.ID]; ok {
		writeError(w, http.StatusConflict, "pool_exists")
		return
	}
	for _, d := range in.Devices {
		if _, busy := s.deviceOwner[d.ID]; busy {
			writeError(w, http.StatusConflict, "device_in_use")
			return
		}
	}

	devices := append([]deviceInput(nil), in.Devices...)
	p := &pool{
		id:           in.ID,
		devices:      devices,
		rawCapacity:  rawCapacity,
		reservations: make(map[string]reservation),
		tenantUsed:   make(map[string]int64),
		quotas:       make(map[string]int64),
	}
	s.pools[in.ID] = p
	for _, d := range devices {
		s.deviceOwner[d.ID] = in.ID
	}
	s.appendAudit(auditPoolCreated, storagePoolPath+"/"+in.ID, in.ID, 0)
	writeJSON(w, http.StatusCreated, p.view())
}

func (s *store) deletePool(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.pools[id]
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	if len(p.reservations) > 0 || p.volumeBytes > 0 || p.snapshotBytes > 0 || p.objectBytes > 0 {
		writeError(w, http.StatusConflict, "pool_not_empty")
		return
	}
	// An empty bucket still blocks pool deletion even though it charges no
	// bytes.
	for _, b := range s.buckets {
		if b.poolID == id {
			writeError(w, http.StatusConflict, "pool_not_empty")
			return
		}
	}
	for _, d := range p.devices {
		delete(s.deviceOwner, d.ID)
	}
	delete(s.pools, id)
	s.appendAudit(auditPoolDeleted, storagePoolPath+"/"+id, id, 0)
	w.WriteHeader(http.StatusNoContent)
}

func (s *store) createReservation(w http.ResponseWriter, r *http.Request, poolID string) {
	var in reservationInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	tenant, tok := extractTenant(r.Header)
	if !tok || !validID(poolID) || !validID(in.RequestID) || in.Bytes <= 0 {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.pools[poolID]
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	if existing, dup := p.reservations[in.RequestID]; dup {
		if existing.bytes != in.Bytes || existing.tenant != tenant {
			writeError(w, http.StatusConflict, "idempotency_conflict")
			return
		}
		writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
		return
	}
	// Holding the store lock makes the quota and capacity checks plus the
	// charge atomic, so concurrent creates can never exceed either limit.
	if p.tenantQuotaExceeded(tenant, in.Bytes) {
		writeError(w, http.StatusConflict, "tenant_quota_exceeded")
		return
	}
	allocated := p.allocated()
	if allocated > p.rawCapacity-in.Bytes {
		writeError(w, http.StatusConflict, "insufficient_capacity")
		return
	}
	p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes, tenant: tenant}
	p.tenantUsed[tenant] += in.Bytes
	s.appendAudit(auditReservationCreated,
		storagePoolPath+"/"+poolID+"/reservations/"+in.RequestID, poolID, in.Bytes)
	writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
}

func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
	if !validID(poolID) || !validID(requestID) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.pools[poolID]
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	// Deleting an unknown or already-deleted reservation is a success with
	// no state change, so only a real deletion records an event.
	if r, existed := p.reservations[requestID]; existed {
		delete(p.reservations, requestID)
		p.tenantUsed[r.tenant] -= r.bytes
		s.appendAudit(auditReservationDeleted,
			storagePoolPath+"/"+poolID+"/reservations/"+requestID, poolID, -r.bytes)
	}
	w.WriteHeader(http.StatusNoContent)
}

package server

import (
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
)

// auditAction enumerates the recorded state-changing operations. Failures,
// read-only requests and successful requests that change no state are never
// recorded.
type auditAction string

const (
	auditPoolCreated        auditAction = "pool.created"
	auditPoolDeleted        auditAction = "pool.deleted"
	auditReservationCreated auditAction = "reservation.created"
	auditReservationDeleted auditAction = "reservation.deleted"
	auditVolumeCreated      auditAction = "volume.created"
	auditVolumeDeleted      auditAction = "volume.deleted"
	auditVolumeBound        auditAction = "volume.bound"
	auditVolumeUnbound      auditAction = "volume.unbound"
	auditVolumeResized      auditAction = "volume.resized"
	auditVolumeRestored     auditAction = "volume.restored"
	auditSnapshotCreated    auditAction = "snapshot.created"
	auditSnapshotDeleted    auditAction = "snapshot.deleted"
	auditCloneCreated       auditAction = "clone.created"
	auditBucketCreated      auditAction = "bucket.created"
	auditBucketDeleted      auditAction = "bucket.deleted"
	auditObjectCreated      auditAction = "object.created"
	auditObjectOverwritten  auditAction = "object.overwritten"
	auditObjectDeleted      auditAction = "object.deleted"
	auditBucketVersioning   auditAction = "bucket.versioning-enabled"
	auditObjectVersioned    auditAction = "object.version-created"
	auditObjectMarker       auditAction = "object.delete-marker-created"
	auditObjectVersionDel   auditAction = "object.version-deleted"
	auditTenantQuotaCreated auditAction = "tenant-quota.created"
	auditTenantQuotaUpdated auditAction = "tenant-quota.updated"
	auditTenantQuotaDeleted auditAction = "tenant-quota.deleted"
)

// auditEventView is the public representation of an audit event.
type auditEventView struct {
	Sequence   int64  `json:"sequence"`
	Action     string `json:"action"`
	Resource   string `json:"resource"`
	PoolID     string `json:"poolId"`
	BytesDelta int64  `json:"bytesDelta"`
}

// auditEvent is one entry of the in-memory audit log. Events are appended
// while holding the store write lock in the same critical section as the
// business state and capacity counters, so an event and the change it
// describes commit atomically: a committed response is always followed by a
// visible event, and a failure leaves no event. The log lives in memory and
// is wiped on restart.
type auditEvent struct {
	sequence   int64
	action     auditAction
	resource   string
	poolID     string
	bytesDelta int64
}

func (e *auditEvent) view() auditEventView {
	return auditEventView{
		Sequence:   e.sequence,
		Action:     string(e.action),
		Resource:   e.resource,
		PoolID:     e.poolID,
		BytesDelta: e.bytesDelta,
	}
}

// appendAudit assigns the next sequence and appends an event. The caller must
// hold s.mu for writing; numbering inside the commit critical section orders
// concurrent commits by the order in which they actually committed.
func (s *store) appendAudit(action auditAction, resource, poolID string, bytesDelta int64) {
	s.auditSeq++
	s.auditEvents = append(s.auditEvents, auditEvent{
		sequence:   s.auditSeq,
		action:     action,
		resource:   resource,
		poolID:     poolID,
		bytesDelta: bytesDelta,
	})
}

// auditEventsPath is the route constant for the audit events endpoint.
const auditEventsPath = "/v1/audit-events"

// auditEventsQuery is the parsed GET /v1/audit-events query.
type auditEventsQuery struct {
	after   int64
	limit   int
	poolID  string
	hasPool bool
}

// parseAuditEventsQuery accepts an empty query or any combination of the
// "after", "limit" and "poolId" parameters, each given at most once and always
// with a value. Defaults are after=0, limit=100, no pool filter. Duplicated,
// unknown, value-less or malformed parameters yield ok=false.
func parseAuditEventsQuery(raw string) (auditEventsQuery, bool) {
	q := auditEventsQuery{limit: 100}
	if raw == "" {
		return q, true
	}
	seenAfter, seenLimit, seenPool := false, false, false
	for _, pair := range strings.Split(raw, "&") {
		k, value, found := strings.Cut(pair, "=")
		if !found {
			return q, false
		}
		key, err := url.QueryUnescape(k)
		if err != nil {
			return q, false
		}
		decoded, err := url.QueryUnescape(value)
		if err != nil {
			return q, false
		}
		switch key {
		case "after":
			if seenAfter || !isNonNegativeDecimal(decoded) {
				return q, false
			}
			seenAfter = true
			n, err := strconv.ParseInt(decoded, 10, 64)
			if err != nil {
				return q, false
			}
			q.after = n
		case "limit":
			if seenLimit || !isNonNegativeDecimal(decoded) {
				return q, false
			}
			seenLimit = true
			n, err := strconv.ParseInt(decoded, 10, 64)
			if err != nil || n < 1 || n > 1000 {
				return q, false
			}
			q.limit = int(n)
		case "poolId":
			if seenPool || decoded == "" || !validID(decoded) {
				return q, false
			}
			seenPool = true
			q.poolID = decoded
			q.hasPool = true
		default:
			return q, false
		}
	}
	return q, true
}

// isNonNegativeDecimal reports whether s is one or more ASCII decimal digits,
// rejecting signs, spaces and exponent notation.
func isNonNegativeDecimal(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// auditEventsList is the response envelope.
type auditEventsList struct {
	Items     []auditEventView `json:"items"`
	NextAfter int64            `json:"nextAfter"`
	HasMore   bool             `json:"hasMore"`
}

// listAuditEvents handles GET /v1/audit-events. The whole page is selected
// under a single read lock, so items and hasMore describe one consistent read
// state even while other requests commit new events.
func (s *store) listAuditEvents(w http.ResponseWriter, r *http.Request) {
	q, ok := parseAuditEventsQuery(r.URL.RawQuery)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.RLock()
	defer s.mu.RUnlock()
	if q.hasPool {
		if _, exists := s.pools[q.poolID]; !exists {
			writeError(w, http.StatusNotFound, "pool_not_found")
			return
		}
	}

	// Sequences are dense and the slice is append-only, so index order is
	// sequence order. Jump to the first event with sequence > after.
	first := sort.Search(len(s.auditEvents), func(i int) bool {
		return s.auditEvents[i].sequence > q.after
	})
	items := make([]auditEventView, 0, q.limit)
	hasMore := false
	for i := first; i < len(s.auditEvents); i++ {
		e := s.auditEvents[i]
		if q.hasPool && e.poolID != q.poolID {
			continue
		}
		if len(items) >= q.limit {
			// A matching event beyond the page (in this same read state)
			// remains.
			hasMore = true
			break
		}
		items = append(items, e.view())
	}
	nextAfter := q.after
	if len(items) > 0 {
		nextAfter = items[len(items)-1].Sequence
	}
	writeJSON(w, http.StatusOK, auditEventsList{Items: items, NextAfter: nextAfter, HasMore: hasMore})
}

