1	package server
2	
3	import (
4		"net/http"
5		"sort"
6	)
7	
8	// tenantHeader is the request header naming the tenant a new reservation,
9	// volume or bucket belongs to. It is already in Go's canonical header form.
10	const tenantHeader = "X-Vaultgrid-Tenant"
11	
12	// defaultTenant owns every resource created without a tenant header.
13	const defaultTenant = "default"
14	
15	// tenantQuotaPath builds the public resource path of one tenant quota.
16	func tenantQuotaPath(poolID, tenantID string) string {
17		return storagePoolPath + "/" + poolID + "/tenant-quotas/" + tenantID
18	}
19	
20	// extractTenant reads the optional X-Vaultgrid-Tenant header. Absent means the
21	// default tenant; more than one value or a value that is not a valid id makes
22	// the whole request invalid.
23	func extractTenant(h http.Header) (string, bool) {
24		values, present := h[tenantHeader]
25		if !present || len(values) == 0 {
26			return defaultTenant, true
27		}
28		if len(values) != 1 || !validID(values[0]) {
29			return "", false
30		}
31		return values[0], true
32	}
33	
34	// tenantQuotaExceeded reports whether charging delta more bytes to tenant in
35	// pool p would exceed the tenant's configured quota. Tenants without a quota
36	// are unlimited. delta must be positive.
37	func (p *pool) tenantQuotaExceeded(tenant string, delta int64) bool {
38		limit, ok := p.quotas[tenant]
39		if !ok {
40			return false
41		}
42		return p.tenantUsed[tenant] > limit-delta
43	}
44	
45	// tenantQuotaInput is the body of PUT .../tenant-quotas/{tenantId}.
46	type tenantQuotaInput struct {
47		LimitBytes int64 `json:"limitBytes"`
48	}
49	
50	// tenantQuotaView is the public representation of one tenant quota.
51	type tenantQuotaView struct {
52		PoolID         string `json:"poolId"`
53		TenantID       string `json:"tenantId"`
54		LimitBytes     int64  `json:"limitBytes"`
55		UsedBytes      int64  `json:"usedBytes"`
56		AvailableBytes int64  `json:"availableBytes"`
57	}
58	
59	// quotaView renders the quota of tenant in pool p. The caller must hold s.mu.
60	func (p *pool) quotaView(tenant string, limit int64) tenantQuotaView {
61		used := p.tenantUsed[tenant]
62		return tenantQuotaView{
63			PoolID:         p.id,
64			TenantID:       tenant,
65			LimitBytes:     limit,
66			UsedBytes:      used,
67			AvailableBytes: limit - used,
68		}
69	}
70	
71	// listTenantQuotas handles GET /v1/storage-pools/{poolId}/tenant-quotas.
72	func (s *store) listTenantQuotas(w http.ResponseWriter, poolID string) {
73		if !validID(poolID) {
