3	import (
4		"fmt"
5		"net/http"
6		"net/http/httptest"
7		"sync"
8		"testing"
9	)
10	
11	func snapURL(volumeID string) string {
12		return "/v1/volumes/" + volumeID + "/snapshots"
13	}
14	
15	func createSnapshot(t *testing.T, h http.Handler, volumeID, body string) *httptest.ResponseRecorder {
16		t.Helper()
17		rec := do(h, http.MethodPost, snapURL(volumeID), body)
18		if rec.Code != http.StatusCreated {
19			t.Fatalf("create snapshot status = %d body = %s", rec.Code, rec.Body.String())
20		}
21		return rec
22	}
23	
24	func getPoolView(t *testing.T, h http.Handler, id string) map[string]any {
25		t.Helper()
26		return decodeBody(t, do(h, http.MethodGet, "/v1/storage-pools/"+id, ""))
27	}
28	
29	func TestCreateSnapshotRepresentationAndCharging(t *testing.T) {
30		h := Handler()
31		createPool(t, h, volPool)
32		createVol(t, h, `{"id":"vol1","poolId":"vp","sizeBytes":300}`)
33	
34		rec := createSnapshot(t, h, "vol1", `{"id":"snap-1","expectedGeneration":0}`)
35		s := decodeBody(t, rec)
36		if s["id"] != "snap-1" || s["sourceVolumeId"] != "vol1" || s["poolId"] != "vp" {
37			t.Fatalf("snapshot identity fields = %v", s)
38		}
39		if s["sizeBytes"].(float64) != 300 || s["sourceGeneration"].(float64) != 0 {
40			t.Fatalf("snapshot size/generation = %v", s)
41		}
42	
43		// The snapshot charges the source pool on top of the source volume.
44		p := getPoolView(t, h, "vp")
45		if p["allocatedBytes"].(float64) != 600 || p["availableBytes"].(float64) != 400 {
46			t.Fatalf("pool after snapshot = %v", p)
47		}
48	
49		// The snapshot records the generation it was taken at.
50		if rec := do(h, http.MethodPut, "/v1/volumes/vol1/binding", `{"nodeId":"n1","expectedGeneration":0}`); rec.Code != http.StatusOK {
51			t.Fatalf("bind = %d", rec.Code)
52		}
53		if rec := do(h, http.MethodDelete, "/v1/volumes/vol1/binding?expectedGeneration=1", ""); rec.Code != http.StatusNoContent {
54			t.Fatalf("unbind = %d", rec.Code)
55		}
56		rec = do(h, http.MethodPost, snapURL("vol1"), `{"id":"snap-2","expectedGeneration":2}`)
57		if rec.Code != http.StatusCreated || decodeBody(t, rec)["sourceGeneration"].(float64) != 2 {
58			t.Fatalf("generation-2 snapshot = %d %s", rec.Code, rec.Body.String())
59		}
60	}
61	
62	func TestCreateSnapshotErrors(t *testing.T) {
63		h := Handler()
64		createPool(t, h, volPool)
65		createVol(t, h, `{"id":"vol1","poolId":"vp","sizeBytes":10}`)
66	
67		wantError(t, do(h, http.MethodPost, snapURL("missing"), `{"id":"s1","expectedGeneration":0}`),
68			http.StatusNotFound, "volume_not_found")
69	
70		// Bound volumes cannot be snapshotted; in-use takes precedence over a
71		// stale generation.
72		if rec := do(h, http.MethodPut, "/v1/volumes/vol1/binding", `{"nodeId":"n1","expectedGeneration":0}`); rec.Code != http.StatusOK {
73			t.Fatalf("bind = %d", rec.Code)
74		}
75		wantError(t, do(h, http.MethodPost, snapURL("vol1"), `{"id":"s1","expectedGeneration":1}`),
76			http.StatusConflict, "volume_in_use")
77		wantError(t, do(h, http.MethodPost, snapURL("vol1"), `{"id":"s1","expectedGeneration":0}`),
78			http.StatusConflict, "volume_in_use")
79		if rec := do(h, http.MethodDelete, "/v1/volumes/vol1/binding?expectedGeneration=1", ""); rec.Code != http.StatusNoContent {
80			t.Fatalf("unbind = %d", rec.Code)
