84		wantError(t, do(h, http.MethodPost, snapURL("vol1"), `{"id":"s1","expectedGeneration":0}`),
85			http.StatusConflict, "stale_generation")
86		wantError(t, do(h, http.MethodPost, snapURL("vol1"), `{"id":"s1","expectedGeneration":1}`),
87			http.StatusConflict, "stale_generation")
88	
