370		h := Handler()
371		createPool(t, h, `{"id":"cp","devices":[{"id":"d","capacityBytes":1000,"faultDomain":"fd"}]}`)
372		createVol(t, h, `{"id":"vol1","poolId":"cp","sizeBytes":100}`)
