374		const goroutines = 30
375		var wg sync.WaitGroup
376		statuses := make(chan int, goroutines)
377		wg.Add(goroutines)
378		for i := 0; i < goroutines; i++ {
379			go func() {
380				defer wg.Done()
381				statuses <- do(h, http.MethodPost, snapURL("vol1"), `{"id":"same","expectedGeneration":0}`).Code
382			}()
