187	func TestReservationLifecycle(t *testing.T) {
188		h := Handler()
189		createPool(t, h, poolA)
190	
191		rec := reserve(t, h, "pool-a", `{"requestId":"r1","bytes":600}`)
192		if rec.Code != http.StatusCreated {
193			t.Fatalf("reserve status = %d %s", rec.Code, rec.Body.String())
194		}
195		v := decodeBody(t, rec)
196		if v["requestId"] != "r1" || v["bytes"].(float64) != 600 || v["poolId"] != "pool-a" {
197			t.Fatalf("reservation view = %v", v)
198		}
199	
200		// Pool view reflects allocation immediately.
201		p := decodeBody(t, do(h, http.MethodGet, "/v1/storage-pools/pool-a", ""))
202		if p["allocatedBytes"].(float64) != 600 || p["availableBytes"].(float64) != 900 {
203			t.Fatalf("pool after reserve = %v", p)
204		}
205	
206		// Same requestId+bytes retried: 200, original result, no double count.
207		rec = reserve(t, h, "pool-a", `{"requestId":"r1","bytes":600}`)
208		if rec.Code != http.StatusOK {
209			t.Fatalf("retry status = %d", rec.Code)
210		}
211		p = decodeBody(t, do(h, http.MethodGet, "/v1/storage-pools/pool-a", ""))
212		if p["allocatedBytes"].(float64) != 600 {
213			t.Fatalf("allocated changed after retry: %v", p["allocatedBytes"])
214		}
215	
216		// Same requestId, different bytes: conflict.
217		wantError(t, reserve(t, h, "pool-a", `{"requestId":"r1","bytes":10}`), http.StatusConflict, "idempotency_conflict")
218	
219		// Insufficient capacity.
220		wantError(t, reserve(t, h, "pool-a", `{"requestId":"r2","bytes":901}`), http.StatusConflict, "insufficient_capacity")
221	
222		// Exactly at the limit succeeds.
223		rec = reserve(t, h, "pool-a", `{"requestId":"r2","bytes":900}`)
224		if rec.Code != http.StatusCreated {
225			t.Fatalf("edge reserve status = %d %s", rec.Code, rec.Body.String())
226		}
227		wantError(t, reserve(t, h, "pool-a", `{"requestId":"r3","bytes":1}`), http.StatusConflict, "insufficient_capacity")
228	
229		// Invalid reservation bodies.
230		for _, body := range []string{
231			`{"requestId":"bad id","bytes":1}`,
232			`{"requestId":"r9","bytes":0}`,
233			`{"requestId":"r9","bytes":-1}`,
234			`{"requestId":"r9","bytes":1.5}`,
235			`{"requestId":"","bytes":1}`,
236			`{"bytes":1}`,
237			`{"requestId":"r9"}`,
238			`{"requestId":"r9","bytes":1,"extra":2}`,
239			`not json`,
240		} {
241			wantError(t, reserve(t, h, "pool-a", body), http.StatusBadRequest, "invalid_request")
242		}
243	
244		// Delete releases capacity; repeated delete still 204.
245		rec = do(h, http.MethodDelete, "/v1/storage-pools/pool-a/reservations/r2", "")
246		if rec.Code != http.StatusNoContent {
247			t.Fatalf("delete reservation = %d", rec.Code)
248		}
249		rec = do(h, http.MethodDelete, "/v1/storage-pools/pool-a/reservations/r2", "")
250		if rec.Code != http.StatusNoContent {
251			t.Fatalf("repeat delete = %d", rec.Code)
252		}
253		p = decodeBody(t, do(h, http.MethodGet, "/v1/storage-pools/pool-a", ""))
254		if p["allocatedBytes"].(float64) != 600 || p["availableBytes"].(float64) != 900 {
255			t.Fatalf("pool after release = %v", p)
256		}
257	
258		// Reusing the requestId after delete counts as a fresh reservation.
259		rec = reserve(t, h, "pool-a", `{"requestId":"r2","bytes":800}`)
260		if rec.Code != http.StatusCreated {
261			t.Fatalf("reuse after delete = %d %s", rec.Code, rec.Body.String())
262		}
263	}
